'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var dorgl2 = require( './../lib' );

// Specify matrix meta data:
var shape = [ 3, 4 ];
var order = 'row-major';
var strides = shape2strides( shape, order );

// The first K rows contain reflector data.
var A = new Float64Array( [ 1.0, 0.2, -0.4, 0.6, 0.0, 1.0, 0.3, -0.8, 0.0, 0.0, 0.0, 0.0 ] );
console.log( 'A(unmodified): ', ndarray2array( A, shape, strides, 0, order ) );

// Define scalar factors of the reflectors and workspace:
var TAU = new Float64Array( [ 0.75, 0.50 ] );
var work = new Float64Array( shape[ 0 ] );

// Generate the orthogonal matrix in-place:
dorgl2( 'row-major', shape[ 0 ], shape[ 1 ], 2, A, strides[ 0 ], TAU, work );
console.log( 'A: ', ndarray2array( A, shape, strides, 0, order ) );
console.log( 'WORK: ', work );

A = new Float64Array( [ 1.0, 0.2, -0.4, 0.6, 0.0, 1.0, 0.3, -0.8, 0.0, 0.0, 0.0, 0.0 ] );

// Define scalar factors of the reflectors and workspace:
TAU = new Float64Array( [ 0.75, 0.50 ] );
work = new Float64Array( shape[ 0 ] );

// Generate the orthogonal matrix in-place:
dorgl2.ndarray( shape[ 0 ], shape[ 1 ], 2, A, strides[ 0 ], strides[ 1 ], 0, TAU, 1, 0, work, 1, 0 );
console.log( 'A: ', ndarray2array( A, shape, strides, 0, order ) );
console.log( 'WORK: ', work );
